def table(headers, rows, numeric=False):
 s='<div class="scroll-wrap"><table><thead><tr>'+''.join('<th scope="col">'+E(h)+'</th>' for h in headers)+'</tr></thead><tbody>'
 for row in rows:
  s+='<tr><th scope="row">'+E(row[0])+'</th>'+''.join('<td'+(' class="num"' if numeric or re.match(r'^\d+(?:\.\d+)?(?:〜\d+(?:\.\d+)?)?%',str(v)) else '')+'>'+E(str(v))+'</td>' for v in row[1:])+'</tr>'
 return s+'</tbody></table></div>'

def chart(a):
 rows=list(csv.reader((R/(a['pair']+'-normalized.csv')).open()))[1:]
 ymax=math.ceil(max(float(v) for r in rows for v in r[1:])/100)*100
 points=[]
 for c in [1,2]:
  pts=' '.join(f'{48+i/(len(rows)-1)*334:.1f},{204-float(r[c])/ymax*166:.1f}' for i,r in enumerate(rows))
  points.append(f'<polyline points="{pts}" fill="none" stroke="var(--accent)" stroke-width="2.5"'+(' stroke-dasharray="7 5"' if c==2 else '')+'/>')
 return '<figure class="figure"><svg viewBox="0 0 400 250" role="img" aria-label="'+E('開始日を100とした分配金再投資基準価額。実線は'+a['names'][0]+'、破線は'+a['names'][1])+'"><path d="M48 38V204H382" fill="none" stroke="currentColor"/><text x="7" y="47" fill="currentColor" font-size="22">'+str(ymax)+'</text><text x="18" y="208" fill="currentColor" font-size="22">0</text>'+''.join(points)+'<text x="48" y="237" fill="currentColor" font-size="22">開始日</text><text x="309" y="237" fill="currentColor" font-size="22">終了日</text></svg><figcaption>開始日を100に統一。実線：'+E(a['names'][0])+'。破線：'+E(a['names'][1])+'。税引前の分配金を再投資した推移です。期間と数値は直上の表に記載。</figcaption></figure>'

